		const SKIN_CSS = `
html[data-nijika-theme] button.nijika-theme-switch{
  --nijika-switch-width:60px;
  position:relative;display:inline-flex;flex:none;align-items:center;justify-content:center;
  width:var(--nijika-switch-width);height:30px;padding:0;border:0;border-radius:999px;
  background:none;box-shadow:none;cursor:pointer;outline-offset:3px;
  vertical-align:middle;align-self:center;-webkit-app-region:no-drag;
}
html[data-nijika-theme] button.nijika-theme-switch[data-fallback]{float:inline-end;margin-inline:8px 6px}
html[data-nijika-theme] button.nijika-theme-switch:hover{box-shadow:none}
body:has([role="dialog"][aria-modal="true"]:not([hidden]):not([aria-hidden="true"])) .nijika-theme-switch{visibility:hidden}
.nijika-theme-switch-track{
  position:absolute;inset:0;border-radius:inherit;overflow:hidden;
  border:1px solid var(--dsw-alias-border-l3,#c96a1040);
  background:linear-gradient(150deg,#fffaf4,#f6ead9);
  box-shadow:inset 0 1px 3px #c96a1022;
  transition:background .38s ease,border-color .38s ease;
}
body[data-ds-dark-theme] .nijika-theme-switch-track{
  background:linear-gradient(150deg,#2f2921,#13100e);
  border-color:var(--dsw-alias-border-l3,#ff9e3d57);
  box-shadow:inset 0 1px 3px #0008;
}
.nijika-theme-switch-orb{
  box-sizing:border-box;position:absolute;top:2px;left:2px;width:24px;height:24px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  border:1px solid #d98b2f;
  background:radial-gradient(circle at 35% 30%,#ffe9c9,#ffb056);
  box-shadow:0 1px 3px #c96a1055,0 0 0 3px #ffffff55;
  color:#7a3c05;font-size:13px;line-height:1;
  transition:transform .42s cubic-bezier(.25,.8,.25,1),background .38s ease,box-shadow .38s ease,color .38s ease;
}
body[data-ds-dark-theme] .nijika-theme-switch-orb{
  transform:translateX(32px);border-color:#ffb056;
  background:radial-gradient(circle at 35% 30%,#ffd79a,#ff9e3d);
  box-shadow:0 1px 3px #0009,0 0 0 3px #ff9e3d26;color:#2b1606;
}
.nijika-theme-switch-glyph{position:absolute;transition:opacity .3s ease,transform .3s ease}
.nijika-theme-switch-glyph--moon{opacity:0;transform:rotate(-40deg) scale(.7)}
.nijika-theme-switch[aria-pressed="true"] .nijika-theme-switch-glyph--sun{opacity:0;transform:rotate(40deg) scale(.7)}
.nijika-theme-switch[aria-pressed="true"] .nijika-theme-switch-glyph--moon{opacity:1;transform:none}
.nijika-theme-switch:hover .nijika-theme-switch-track{border-color:var(--dsw-alias-brand-primary,#c96a10)}
.nijika-theme-switch:focus-visible{outline:2px solid var(--dsw-alias-brand-primary,#c96a10)}

/* 从开关小球的位置揭开新色板（eva 同款圆形扩散转场）。按钮单独合成，保留滑动动画。 */
html[data-nijika-theme-reveal] .nijika-theme-switch{view-transition-name:nijika-theme-switch}
html[data-nijika-theme-reveal]::view-transition{pointer-events:none}
html[data-nijika-theme-reveal]::view-transition-group(root),
html[data-nijika-theme-reveal]::view-transition-group(nijika-theme-switch),
html[data-nijika-theme-reveal]::view-transition-old(root),
html[data-nijika-theme-reveal]::view-transition-new(nijika-theme-switch){animation:none}
html[data-nijika-theme-reveal]::view-transition-group(nijika-theme-switch){z-index:1}
html[data-nijika-theme-reveal]::view-transition-old(nijika-theme-switch){display:none}
html[data-nijika-theme-reveal]::view-transition-image-pair(root){isolation:isolate}
html[data-nijika-theme-reveal]::view-transition-new(root){
  mix-blend-mode:normal;animation:nijika-theme-reveal .56s cubic-bezier(.25,.7,.25,1) both;
}
@keyframes nijika-theme-reveal{
  from{clip-path:circle(0px at var(--nijika-theme-x) var(--nijika-theme-y))}
  to{clip-path:circle(var(--nijika-theme-radius) at var(--nijika-theme-x) var(--nijika-theme-y))}
}
@media(prefers-reduced-motion:reduce){
  .nijika-theme-switch-orb,.nijika-theme-switch-glyph,.nijika-theme-switch-track{transition:none}
  html[data-nijika-theme-reveal]::view-transition-new(root){animation:none}
}
`;

		// ============================================================
		// 装饰层：结束乐队鼓手（伊地知虹夏）的味道 —— 暖色环境光、
